# Configuration file for the Sphinx documentation builder.
#
# For the full list of options, see the documentation:
# https://www.sphinx-doc.org/en/master/usage/configuration.html

# The tutorial notebooks and the demo report are generated by `scripts/prepare_docs.py`,
# which must run before sphinx-build. shapash is imported from the installed package.
import os
from datetime import date

import shapash

# -- Project information -----------------------------------------------------

project = "Shapash"
copyright = f"2020-{date.today().year}, Maif"
author = "Maif"
version = shapash.__version__
release = shapash.__version__

# -- General configuration ---------------------------------------------------

extensions = [
    "sphinx.ext.autodoc",
    "sphinx.ext.autosummary",
    "sphinx.ext.intersphinx",
    "sphinx.ext.napoleon",
    "sphinx.ext.viewcode",
    "myst_nb",
    "sphinx_copybutton",
    "sphinx_design",
]

root_doc = "index"
templates_path = ["_templates"]
language = "en"
# Markdown files are not documentation pages (GitHub wiki sources, landing page assets).
# `assets/` belongs to the GitHub Pages landing page served from this folder.
exclude_patterns = ["_build", "_generated", "assets", "**.md", "Thumbs.db", ".DS_Store"]

# -- API reference -----------------------------------------------------------

autosummary_generate = True
autodoc_default_options = {"members": True, "show-inheritance": True}
autodoc_member_order = "bysource"
autodoc_typehints = "description"
# "block_header()" rather than "ReportBlockMixin.block_header()" in the page table of contents
toc_object_entries_show_parents = "hide"
# The torch adapters subclass torch classes at import time; torch is not installed to build the docs.
autodoc_mock_imports = ["torch"]
napoleon_numpy_docstring = True
napoleon_google_docstring = False

# Linking to these projects downloads their inventories at build time. Set SHAPASH_DOCS_OFFLINE=1 to
# build without network access (behind a proxy, for example): their types then render as plain text.
intersphinx_mapping = {
    "python": ("https://docs.python.org/3", None),
    "numpy": ("https://numpy.org/doc/stable/", None),
    "pandas": ("https://pandas.pydata.org/docs/", None),
    "sklearn": ("https://scikit-learn.org/stable/", None),
    "plotly": ("https://plotly.com/python-api-reference/", None),
}
if os.environ.get("SHAPASH_DOCS_OFFLINE") == "1":
    intersphinx_mapping = {}

# -- Notebooks ---------------------------------------------------------------

# Tutorials are rendered with the outputs saved in the notebooks: running them takes too long.
nb_execution_mode = "off"
# Notebooks skip heading levels (H2 to H4), and some saved outputs carry an extra VS Code Data Wrangler
# representation next to the HTML one, which is rendered instead.
suppress_warnings = ["myst.header", "mystnb.unknown_mime_type"]

# -- Options for HTML output -------------------------------------------------

html_theme = "pydata_sphinx_theme"
html_title = f"Shapash {release}"
html_logo = "_static/shapash-resize.png"
html_favicon = "assets/images/logos/favicon.png"
html_static_path = ["_static"]
html_css_files = ["css/custom.css"]
html_theme_options = {
    "github_url": "https://github.com/MAIF/shapash",
    "icon_links": [
        {"name": "PyPI", "url": "https://pypi.org/project/shapash/", "icon": "fa-brands fa-python"},
    ],
    "navigation_with_keys": False,
    "show_toc_level": 2,
}
# These pages have no sub-pages, so the section navigation would be empty
html_sidebars = {"overview": [], "installation-instructions/index": []}
html_context = {
    "github_user": "MAIF",
    "github_repo": "shapash",
    "github_version": "master",
    "doc_path": "docs",
}

# Demo report linked from the README as `report.html`
html_extra_path = ["_generated/report.html"]
